        opts: ['Que la prova no val: cal fer-la amb exemples nous|Que la prueba no vale: hay que hacerla con ejemplos nuevos', 'Que és perfecta|Que es perfecta', 'Que cal pujar la temperatura|Que hay que subir la temperatura'], a: 0,
